def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = []
    op = []
    op_c = 0
    for i in range(n):
        a, b = history[i]
        my.append(a)
        op.append(b)
        if b == 'C':
            op_c += 1
    op_d = n - op_c

    if n >= 2 and op_c == 0:
        return 'D'

    r = 100 - n

    recent_len = 10 if n >= 10 else n
    rc = 0
    for i in range(n - recent_len, n):
        if op[i] == 'C':
            rc += 1
    recent_rate = rc / float(recent_len)
    overall_rate = op_c / float(n)
    base = 0.65 * recent_rate + 0.35 * overall_rate
    if base < 0.05:
        base = 0.05
    if base > 0.95:
        base = 0.95

    cntC = 0.0
    respC = 0.0
    cntD = 0.0
    respD = 0.0
    for i in range(1, n):
        w = 2.0 if (n - i) <= 10 else 1.0
        if my[i - 1] == 'C':
            cntC += w
            if op[i] == 'C':
                respC += w
        else:
            cntD += w
            if op[i] == 'C':
                respD += w

    rawC = respC / cntC if cntC > 0.0 else base
    rawD = respD / cntD if cntD > 0.0 else 0.0

    use_dp = False
    if r <= 5:
        if cntD >= 2.0 and rawD >= 0.6 and base > 0.6:
            use_dp = True
    elif r <= 12:
        if cntD >= 2.0 and rawD >= 0.65 and base > 0.65:
            use_dp = True

    if use_dp:
        priorC = base
        priorD = max(0.08, min(0.45, base * 0.25))
        pw = 0.8

        if cntC > 0.0:
            qC = (respC + priorC * pw) / (cntC + pw)
        else:
            qC = priorC

        if cntD > 0.0:
            qD = (respD + priorD * pw) / (cntD + pw)
        else:
            qD = priorD

        if qC < 0.02:
            qC = 0.02
        if qC > 0.98:
            qC = 0.98
        if qD < 0.02:
            qD = 0.02
        if qD > 0.98:
            qD = 0.98

        state = 0 if my[-1] == 'C' else 1

        vc = [0.0] * (r + 1)
        vd = [0.0] * (r + 1)
        ac = ['C'] * (r + 1)
        ad = ['C'] * (r + 1)

        for t in range(1, r + 1):
            valC = 3.0 * qC + vc[t - 1]
            valD = 1.0 + 4.0 * qC + vd[t - 1]
            if valD > valC + 1e-12:
                ac[t] = 'D'
                vc[t] = valD
            else:
                ac[t] = 'C'
                vc[t] = valC

            valC = 3.0 * qD + vc[t - 1]
            valD = 1.0 + 4.0 * qD + vd[t - 1]
            if valD > valC + 1e-12:
                ad[t] = 'D'
                vd[t] = valD
            else:
                ad[t] = 'C'
                vd[t] = valC

        if state == 0:
            return ac[r]
        return ad[r]

    last = op[-1]
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    if last == 'D':
        if run >= 2:
            return 'D'
        if op_d * 3 > n:
            return 'D'
        if my[-1] == 'D':
            return 'C'
        return 'D'

    if op_c * 5 >= n * 4:
        return 'C'

    if op_d * 2 > n:
        return 'D'

    return 'C'
